<?php
declare(strict_types=1);
require_once __DIR__.'/classification_export.php';

/** Report only the figures and plotted datasets used by the dashboard. */
function dashboardReportSections(array $snapshot):array {
    $d=$snapshot['data'];$department=$snapshot['role']!=='barangay_staff';$sections=[];
    $labels=$department?[
        'verified_applications'=>'Verified applications','senior_citizen_records'=>'Senior citizen records',
        'total_processed'=>'Total processed','system_user_count'=>'Active system users','barangay_staff_count'=>'Barangay staff accounts',
        'pending_senior_id'=>'Pending Senior ID','pending_landbank'=>'Landbank — pending',
        'pending_local_pension'=>'Local Senior Pension — pending','pending_octogenarian'=>'Octogenarian Benefits — pending',
        'pending_burial'=>'Burial Assistance — pending','deceased_records'=>'Deceased records',
    ]:['total_count'=>'Total applications','queue_count'=>'Waiting for action','pending_senior_id'=>'Pending Senior ID','pending_landbank'=>'Pending Landbank'];
    $summary=[];foreach($labels as $key=>$label)$summary[]=[$label,(int)($d[$key]??0)];
    $workflow=[];
    if($department){foreach($d['workflow_stats']??[] as $label=>$count)$workflow[]=[$label,(int)$count];}
    else{foreach($d['workflow_stats']??[] as $row)$workflow[]=[$row['workflow_state'],(int)$row['count']];$verified=0;foreach($workflow as [$label,$count])if($label==='Verified')$verified=$count;$summary[]=['Verified',$verified];}
    $sections[]=['title'=>'Dashboard summary','rows'=>$summary];
    if($department){
        $sections[]=['title'=>'Records by barangay','rows'=>array_map(static fn($r)=>[$r['barangay']?:'Not specified',(int)$r['count']],$d['barangay_records']??[])];
        $sections[]=['title'=>'Yearly records','rows'=>array_map(static fn($r)=>[(string)($r['year']??'Not specified'),(int)$r['count']],$d['yearly_records']??[])];
    }else $sections[]=['title'=>'Workflow status distribution','rows'=>$workflow];
    $trend=[];$months=[];$end=new DateTimeImmutable(substr($snapshot['captured_at'],0,10),new DateTimeZone('Asia/Manila'));$end=$end->modify('first day of this month');
    for($i=11;$i>=0;$i--){$month=$end->modify('-'.$i.' months');$key=$month->format('Y-n');$months[$key]=$month->format('F Y');$trend[$key]=['Female'=>0,'Male'=>0];}
    foreach($d[$department?'gender_monthly_records':'gender_stats']??[] as $r){$key=(int)$r['year'].'-'.(int)$r['month_num'];if(isset($trend[$key][$r['gender']]))$trend[$key][$r['gender']]=(int)$r['count'];}
    $rows=[];foreach($trend as $key=>$genders)foreach($genders as $gender=>$count)$rows[]=[$months[$key].' — '.$gender,$count];
    $sections[]=['title'=>'Female and male senior trend — last 12 months','rows'=>$rows];
    if(!$department){$monthly=[];foreach($d['monthly']??[] as $r)if($r['application_type']==='senior')$monthly[(int)$r['year'].'-'.(int)$r['month_num']]=(int)$r['count'];$rows=[];foreach($months as $key=>$label)$rows[]=[$label,$monthly[$key]??0];$sections[]=['title'=>'Monthly Senior Citizen Applications — last 12 months','rows'=>$rows];}
    return $sections;
}

function dashboardReportExcel(array $sections,array $snapshot,PDO $conn):string {
    $xml=static fn($v)=>htmlspecialchars(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/u','',(string)$v)??'',ENT_XML1|ENT_QUOTES,'UTF-8');
    $rows='';$n=0;$merges=[];
    $write=function(array $values,int $style,float $height=24,bool $numeric=false)use(&$rows,&$n,$xml){$n++;$rows.='<row r="'.$n.'" ht="'.$height.'" customHeight="1">';foreach($values as $i=>$v){$r=chr(65+$i).$n;if($numeric&&$i===2)$rows.='<c r="'.$r.'" s="'.($style===8?9:6).'"><v>'.(int)$v.'</v></c>';else $rows.='<c r="'.$r.'" s="'.$style.'" t="inlineStr"><is><t>'.$xml($v).'</t></is></c>';}$rows.='</row>';};
    $merge=function(string $v,int $style,float $height=24,string $end='C')use($write,&$merges,&$n){$write([$v],$style,$height);$merges[]='A'.$n.':'.$end.$n;};
    $coverage=$snapshot['barangay']??'Pasig City — All Barangays';
    $merge('REPUBLIC OF THE PHILIPPINES',1,20);$merge('CITY GOVERNMENT OF PASIG',2,28);$merge('OFFICE FOR SENIOR CITIZENS AFFAIRS',1,22);$merge($coverage,1,20);$merge('SENIORLINK — Centralized Profiling and Record Management System',3,20);$write([],0,10);
    $merge('DASHBOARD SUMMARY REPORT',4,28);$merge('Coverage: '.$coverage,0,24);$merge('Dashboard data as of: '.$snapshot['captured_at'].' Asia/Manila',0,24);$merge('Summary and yearly figures: all dates. Monthly trend datasets: last 12 displayed months.',3,28);$write(['Dashboard metric or category','','Count'],5,28);$merges[]='A11:B11';
    foreach($sections as $section){$merge($section['title'],7,26);if(!$section['rows'])$merge('No data available.',3);foreach($section['rows'] as $i=>[$label,$count]){$write([$label,'',$count],$i%2?8:0,26,true);$merges[]='A'.$n.':B'.$n;}$write([],0,8);}
    $logos=classificationReportLogos($conn);$drawing='';$drawingRels='';$files=[];$id=0;
    foreach($logos as $name=>$logo){$id++;$col=$name==='Logo'?0:2;$scale=min(76/$logo['width'],76/$logo['height']);$drawing.='<xdr:oneCellAnchor><xdr:from><xdr:col>'.$col.'</xdr:col><xdr:colOff>142875</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>95250</xdr:rowOff></xdr:from><xdr:ext cx="'.(int)($logo['width']*$scale*9525).'" cy="'.(int)($logo['height']*$scale*9525).'"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="'.$id.'" name="'.$name.'"/><xdr:cNvPicPr/></xdr:nvPicPr><xdr:blipFill><a:blip r:embed="rId'.$id.'"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill><xdr:spPr><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:oneCellAnchor>';$drawingRels.='<Relationship Id="rId'.$id.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/'.$name.'.png"/>';$files['xl/media/'.$name.'.png']=$logo['png'];}
    $sheet='<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView showGridLines="0" workbookViewId="0"><pane ySplit="11" topLeftCell="A12" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="25" customWidth="1"/><col min="2" max="2" width="66" customWidth="1"/><col min="3" max="3" width="22" customWidth="1"/></cols><sheetData>'.$rows.'</sheetData><mergeCells count="'.count($merges).'">'.implode('',array_map(static fn($r)=>'<mergeCell ref="'.$r.'"/>',$merges)).'</mergeCells><pageMargins left="0.35" right="0.35" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" paperSize="9" fitToWidth="1" fitToHeight="0"/><headerFooter><oddFooter>&amp;LSENIORLINK Dashboard Summary&amp;RPage &amp;P of &amp;N</oddFooter></headerFooter>'.($logos?'<drawing r:id="rId1"/>':'').'</worksheet>';
    $fonts='';foreach([[11,'17324D',false],[11,'52657B',true],[18,'10365D',true],[10,'60758B',false],[16,'10365D',true],[11,'FFFFFF',true]] as [$size,$color,$bold])$fonts.='<font>'.($bold?'<b/>':'').'<sz val="'.$size.'"/><color rgb="FF'.$color.'"/><name val="Calibri"/></font>';
    $xf=static fn($f,$fill,$align='left',$num=49)=>'<xf fontId="'.$f.'" fillId="'.$fill.'" borderId="0" numFmtId="'.$num.'" applyAlignment="1"><alignment horizontal="'.$align.'" vertical="center" wrapText="1"/></xf>';
    $styles='<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="6">'.$fonts.'</fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF174E7F"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFEAF1F8"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="10">'.$xf(0,0).$xf(1,0,'center').$xf(2,0,'center').$xf(3,0).$xf(4,0).$xf(5,2).$xf(0,0,'right',3).$xf(1,3).$xf(0,3).$xf(0,3,'right',3).'</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>';
    $files+=['[Content_Types].xml'=>'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/></Types>',
        '_rels/.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
        'xl/workbook.xml'=>'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Dashboard Summary" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="_xlnm.Print_Titles" localSheetId="0">&apos;Dashboard Summary&apos;!$1:$11</definedName><definedName name="_xlnm.Print_Area" localSheetId="0">&apos;Dashboard Summary&apos;!$A$1:$C$'.$n.'</definedName></definedNames></workbook>',
        'xl/_rels/workbook.xml.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',
        'xl/styles.xml'=>$styles,'xl/worksheets/sheet1.xml'=>$sheet];
    if($logos){$files['xl/worksheets/_rels/sheet1.xml.rels']='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/></Relationships>';$files['xl/drawings/drawing1.xml']='<?xml version="1.0"?><xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'.$drawing.'</xdr:wsDr>';$files['xl/drawings/_rels/drawing1.xml.rels']='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'.$drawingRels.'</Relationships>';}
    $path=tempnam(sys_get_temp_dir(),'dashboard-report-');if($path===false)throw new RuntimeException('Unable to prepare report.');try{$zip=new ZipArchive();if($zip->open($path,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Unable to create report.');foreach($files as $name=>$data)$zip->addFromString($name,$data);if(!$zip->close())throw new RuntimeException('Unable to finish report.');return (string)file_get_contents($path);}finally{if(is_file($path))unlink($path);}
}

function dashboardReportPdf(array $sections,array $snapshot,PDO $conn):string {
    require_once __DIR__.'/pdf_report_header.php';
    $escape=static function($v){$s=iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',(string)$v);return str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$s===false?'':$s);};
    $text=static fn($x,$y,$v,$size=9,$font='F1')=>'BT /'.$font.' '.$size.' Tf '.$x.' '.$y.' Td ('.$escape($v).') Tj ET';
    $logos=classificationReportLogos($conn);$streams=[];$commands=[];$y=0;
    $newPage=function()use(&$commands,&$streams,&$y,$snapshot,$logos,$escape,$text){if($commands)$streams[]=implode("\n",$commands);$r=['title'=>'DASHBOARD SUMMARY REPORT','subtitle'=>$snapshot['barangay']??'Main OSCA — Pasig City','coverage'=>$snapshot['barangay']??'All Barangays','generated'=>$snapshot['captured_at'],'filters'=>'Dashboard summary and chart data','has_osca_logo'=>isset($logos['OSCA'])];foreach(['Logo'=>'logo','OSCA'=>'osca_logo'] as $name=>$key)if(isset($logos[$name])){$scale=min(64/$logos[$name]['width'],64/$logos[$name]['height']);$r[$key.'_width']=$logos[$name]['width']*$scale;$r[$key.'_height']=$logos[$name]['height']*$scale;}$commands=standardPdfReportHeaderCommands($r,$escape,static fn($v,$n)=>$v,isset($logos['Logo']));$commands[]='0.34 0.42 0.51 rg';$commands[]=$text(36,380,'Dashboard data as of '.$snapshot['captured_at'].' Asia/Manila. Summary/yearly: all dates; monthly trends: last 12 displayed months.',7);$commands[]=$text(36,22,'SENIORLINK | Dashboard totals and chart datasets | No individual application records',7,'F3');$y=357;};
    $newPage();foreach($sections as $section){if($y<100)$newPage();$commands[]='0.08 0.28 0.50 rg 36 '.($y-5).' 770 23 re f';$commands[]='1 1 1 rg';$commands[]=$text(44,$y+2,$section['title'],10,'F2');$y-=28;if(!$section['rows']){$commands[]='0.1 0.18 0.28 rg';$commands[]=$text(44,$y,'No data available.');$y-=22;}foreach($section['rows'] as $i=>[$label,$value]){if($y<52){$newPage();$commands[]='0.08 0.28 0.50 rg 36 '.($y-5).' 770 23 re f';$commands[]='1 1 1 rg';$commands[]=$text(44,$y+2,$section['title'].' (continued)',10,'F2');$y-=28;}if($i%2===1)$commands[]='0.95 0.97 0.99 rg 36 '.($y-5).' 770 17 re f';$commands[]='0.1 0.18 0.28 rg';$commands[]=$text(44,$y,$label);$commands[]=$text(745,$y,number_format($value),9,'F2');$y-=18;}$y-=13;}
    $streams[]=implode("\n",$commands);$objects=[1=>'<< /Type /Catalog /Pages 2 0 R >>',3=>'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',4=>'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',5=>'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>'];$next=6;$resources=[];
    foreach($logos as $name=>$logo){$id=$next++;$objects[$id]='<< /Type /XObject /Subtype /Image /Width '.$logo['width'].' /Height '.$logo['height'].' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '.strlen($logo['jpeg']).">>\nstream\n".$logo['jpeg']."\nendstream";$resources[]='/'.$name.' '.$id.' 0 R';}
    $kids=[];$base=$next;foreach($streams as $i=>$stream){$p=$base+$i*2;$c=$p+1;$kids[]=$p.' 0 R';$stream.="\n0.34 0.42 0.51 rg ".$text(700,22,'Page '.($i+1).' of '.count($streams),7,'F3');$objects[$p]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >> /XObject << '.implode(' ',$resources).' >> >> /Contents '.$c.' 0 R >>';$objects[$c]='<< /Length '.strlen($stream).">>\nstream\n".$stream."\nendstream";}$objects[2]='<< /Type /Pages /Kids ['.implode(' ',$kids).'] /Count '.count($streams).' >>';ksort($objects);$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $id=>$obj){$offsets[$id]=strlen($pdf);$pdf.=$id." 0 obj\n".$obj."\nendobj\n";}$start=strlen($pdf);$pdf.="xref\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";for($i=1;$i<=count($objects);$i++)$pdf.=sprintf("%010d 00000 n \n",$offsets[$i]);return $pdf."trailer\n<< /Size ".(count($objects)+1)." /Root 1 0 R >>\nstartxref\n".$start."\n%%EOF";
}
